<template>
  <Dialog
    :options="{ title: __('Merge with another ticket') }"
    v-model="showDialog"
  >
    <template #body-content>
      <div class="flex flex-col gap-4">
        <!-- //// Neoffice — was one English sentence cut in three by the
             //// interpolation. A fragment cannot be translated: French says
             //// "Tous les commentaires ... du ticket #12 seront déplacés", so the
             //// ticket number sits somewhere else in the sentence. One {0} message
             //// now, split back on the TRANSLATED text so the bold number survives
             //// without a v-html. -->
        <p class="text-p-base text-ink-gray-8">
          {{ warning.before
          }}<span class="whitespace-nowrap font-semibold"
            >#{{ ticket.name }}</span
          >{{ warning.after }}
        </p>
        <Link
          class="form-control"
          doctype="HD Ticket"
          :placeholder="__('Select Ticket')"
          :filters="getDefaultFilters()"
          :label="__('Ticket')"
          :page-length="10"
          :value="targetTicket"
          :show-description="true"
          @change="targetTicket = String($event)"
        />
        <FormControl
          v-if="targetTicket"
          :label="__('Ticket Subject')"
          type="text"
          v-model="subject"
          :disabled="true"
        />
        <!-- banner -->
        <div
          class="flex items-center gap-2 rounded-md p-2 ring-1 ring-gray-200"
        >
          <TriangleAlert
            class="h-6 w-5 w-min-5 w-max-5 min-h-5 max-w-5 text-yellow-500"
          />

          <div class="text-wrap text-sm text-gray-700">
            {{ __("This action is irreversible.") }}
          </div>
        </div>
      </div>
    </template>
    <template #actions>
      <Button
        class="w-full"
        variant="solid"
        :label="
          targetTicket ? `Merge with ticket #${targetTicket} ` : 'Select Ticket'
        "
        :loading="mergeTicket.loading"
        :icon-left="targetTicket && LucideMerge"
        @click="handleTicketMerge"
      />
    </template>
  </Dialog>
</template>

<script setup lang="ts">
import { Link } from "@/components";
import { HDTicket } from "@/types/doctypes";
import { Dialog, createListResource, createResource, toast } from "frappe-ui";
import { computed, ref, watch } from "vue";
import LucideMerge from "~icons/lucide/merge";
import TriangleAlert from "~icons/lucide/triangle-alert";
import { __ } from "@/translation";
// interface P
interface Props {
  ticket: HDTicket;
}

interface E {
  (event: "update"): void;
  //   (event: "rowClick", row: any): void;
}

const props = defineProps<Props>();

//// Neoffice — one message, {0} where the ticket number goes; the halves come back
//// from the translation so each language keeps its own word order.
const warning = computed(() => {
  const [before, after] = __(
    "All comments and emails of the ticket {0} will be moved to the selected ticket."
  ).split("{0}");
  return { before, after: after ?? "" };
});
const emit = defineEmits<E>();
const showDialog = defineModel<boolean>();

interface Filter {
  status_category: [string, string[] | string];
  is_merged: number;
  name: string[];
  customer?: any;
  raised_by?: [string, string[] | string];
}

function getDefaultFilters() {
  const filters: Filter = {
    status_category: ["in", ["Open", "Paused"]],
    is_merged: 0,
    name: ["!=", props.ticket.name],
  };
  // if part of an organization show all tickets of the organization
  if (props.ticket.customer) {
    filters.customer = props.ticket.customer;
  }
  //  show all tickets of the person who raised the ticket
  if (props.ticket.raised_by) {
    filters.raised_by = ["like", `%${props.ticket.raised_by}%`];
  }
  return filters;
}

const targetTicket = ref(null);
const subject = ref(null);

const mergeTicket = createResource({
  url: "helpdesk.helpdesk.doctype.hd_ticket.api.merge_ticket",
  makeParams({ source, target }) {
    return {
      source,
      target,
    };
  },
  validate({ source, target }) {
    if (!source) throw { message: __('Category is required') };
    if (!target) throw { message: __('Ticket to merged with is required') };
  },
  onSuccess: () => {
    toast.success("Ticket merged successfully");
    emit("update");

    showDialog.value = false;
    // open the target Ticket
    window.open(
      window.location.origin + "/helpdesk/tickets/" + targetTicket.value,
      "_blank"
    );
    targetTicket.value = null;
  },
});

const getTicketSubject = createListResource({
  doctype: "HD Ticket",
  filters: {
    name: ["=", targetTicket],
  },
  fields: ["subject"],
  onSuccess: (data: any) => {
    if (data.length > 0) {
      subject.value = data[0].subject;
    }
  },
});

watch(
  () => targetTicket.value,
  (newValue) => {
    if (newValue) {
      getTicketSubject.update({
        filters: {
          name: ["=", newValue],
        },
      });
      getTicketSubject.reload();
    }
  }
);

function handleTicketMerge() {
  mergeTicket.submit({
    source: props.ticket.name,
    target: targetTicket.value,
  });
}
</script>

<style scoped></style>
